#!/bin/bash
# prebmitune.sh for firetv/fastchannels
# 2026.10.17
#
# ah4c "pre" script for FastChannels Player (com.fastchannels.player).
# Generated by FastChannels' "Export ah4c scripts" button — see bmitune.sh for the
# real work; this one just has to be fast, since ah4c runs it before opening the
# encoder connection and it counts against the DVR's ~30s tune budget.
#
# ah4c calls this as: prebmitune.sh <tunerip> <channel>

set -x

TUNERIP="$1"

echo "[STARTING] prebmitune.sh $TUNERIP"

# A stick that reboots or drops off the network leaves this container's adb
# server without it, and nothing else here reconnects it. This used to connect
# only when TUNERIP was a dotted IP, so a tuner named by hostname
# (firestick-capture1:5555) never reconnected after its stick rebooted:
# FastChannels, with its own adb server, still tuned it, but bmitune.sh could
# no longer see playback and failed every tune on it. Any host:port is
# connected now; a USB serial has no colon and needs no connect.
#
# A connected device costs one local query. Reconnecting is bounded, and a
# failure is logged rather than ending the tune: FastChannels does the actual
# tune through its own adb, which may still reach the stick.
ensure_adb() {
	[[ "$TUNERIP" == *:* ]] || return 0
	[ "$(timeout 2 adb -s "$TUNERIP" get-state 2>/dev/null)" == "device" ] && return 0
	adb disconnect "$TUNERIP" >/dev/null 2>&1
	local output
	output=$(timeout 3 adb connect "$TUNERIP" 2>&1)
	echo "$output"
	if [ "$(timeout 2 adb -s "$TUNERIP" get-state 2>/dev/null)" != "device" ]; then
		echo "[WARNING] adb could not connect to $TUNERIP — continuing, bmitune.sh will retry"
	fi
}

ensure_adb

# Wake the device in case it was put to sleep (e.g. ah4c's "sleep all" button).
# A sleeping stick still reports PLAYING once tuned, so bmitune.sh would
# "succeed" while the encoder captures a blank screen. No-op when already awake.
adb -s "$TUNERIP" shell input keyevent KEYCODE_WAKEUP

exit 0
